	# aC|Av
	X['ab'][pv,pA,ha,hC] += 1.0 * np.einsum('vw,VW,wUuV,aWvI->aUuI', eta1['a'], gamma1['b'], h['ab'][a,A,a,A], t['ab'][pv,pA,ha,hC], optimize=True)
