	# cA|Vv
	X['ab'][pv,pV,hc,hA] += -1.0 * np.einsum('uv,VW,aWuU,vAiV->aAiU', eta1['a'], gamma1['b'], h['ab'][v,A,a,A], t['ab'][pa,pV,hc,hA], optimize=True)
