	X['ab'][pv,pV,hc,hA] += -1.0 * np.einsum('VW,uv,vWiU,aAuV->aAiU', eta1['b'], eta1['a'], h['ab'][a,A,c,A], t['ab'][pv,pV,ha,hA], optimize=True)
