	X['ab'][pv,pV,hc,hA] += -1.0 * np.einsum('uv,vAiU,au->aAiU', gamma1['a'], h['ab'][a,V,c,A], t['a'][pv,ha], optimize=True)
	X['ab'][pv,pV,hc,hA] += -1.0 * np.einsum('uv,vAiB,aBuU->aAiU', gamma1['a'], h['ab'][a,V,c,V], t['ab'][pv,pV,ha,hA], optimize=True)
