	# cC|Aa
	X['ab'][pa,pA,hc,hC] += -1.0 * np.einsum('vw,juiv,wUjI->uUiI', eta1['a'], h['aa'][c,a,c,a], t['ab'][pa,pA,hc,hC], optimize=True)
