	X['a'][pv,hc] += -1.0 * np.einsum('uIbA,vUuV,aAiU,bVvI->ai', h['ab'][a,C,v,V], lambdas['ab'], t['ab'][pv,pV,hc,hA], t['ab'][pv,pA,ha,hC], optimize=True)
	X['a'][pv,hc] += 1.0 * np.einsum('uIbA,vUuV,aAvU,bViI->ai', h['ab'][a,C,v,V], lambdas['ab'], t['ab'][pv,pV,ha,hA], t['ab'][pv,pA,hc,hC], optimize=True)
	X['a'][pv,hc] += 1.0 * np.einsum('uIbA,vUuV,bAiU,aVvI->ai', h['ab'][a,C,v,V], lambdas['ab'], t['ab'][pv,pV,hc,hA], t['ab'][pv,pA,ha,hC], optimize=True)
	X['a'][pv,hc] += -1.0 * np.einsum('uIbA,vUuV,bAvU,aViI->ai', h['ab'][a,C,v,V], lambdas['ab'], t['ab'][pv,pV,ha,hA], t['ab'][pv,pA,hc,hC], optimize=True)
	X['a'][pv,hc] += -1.0 * np.einsum('uUbA,vVuU,bi,aAvV->ai', h['ab'][a,A,v,V], lambdas['ab'], t['a'][pv,hc], t['ab'][pv,pV,ha,hA], optimize=True)
	X['a'][pv,hc] += 1.0 * np.einsum('uUbA,vVuU,bv,aAiV->ai', h['ab'][a,A,v,V], lambdas['ab'], t['a'][pv,ha], t['ab'][pv,pV,hc,hA], optimize=True)
	X['a'][pv,hc] += 1.0 * np.einsum('uUbA,vVuU,AV,abiv->ai', h['ab'][a,A,v,V], lambdas['ab'], t['b'][pV,hA], t['aa'][pv,pv,hc,ha], optimize=True)
	X['a'][pv,hc] += 0.5 * np.einsum('uUbA,vwVuxU,abvw,xAiV->ai', h['ab'][a,A,v,V], lambdas['aab'], t['aa'][pv,pv,ha,ha], t['ab'][pa,pV,hc,hA], optimize=True)
	X['a'][pv,hc] += 1.0 * np.einsum('aIuA,uUvV,VI,vAiU->ai', h['ab'][v,C,a,V], lambdas['ab'], t['b'][pA,hC], t['ab'][pa,pV,hc,hA], optimize=True)
	X['a'][pv,hc] += 1.0 * np.einsum('aIuA,uUvV,AU,vViI->ai', h['ab'][v,C,a,V], lambdas['ab'], t['b'][pV,hA], t['ab'][pa,pA,hc,hC], optimize=True)
	X['a'][pv,hc] += 1.0 * np.einsum('aIbU,uUvV,bu,vViI->ai', h['ab'][v,C,v,A], lambdas['ab'], t['a'][pv,ha], t['ab'][pa,pA,hc,hC], optimize=True)
	X['a'][pv,hc] += 1.0 * np.einsum('aIbA,uUvV,bVuI,vAiU->ai', h['ab'][v,C,v,V], lambdas['ab'], t['ab'][pv,pA,ha,hC], t['ab'][pa,pV,hc,hA], optimize=True)
	X['a'][pv,hc] += 1.0 * np.einsum('aIbA,uUvV,bAuU,vViI->ai', h['ab'][v,C,v,V], lambdas['ab'], t['ab'][pv,pV,ha,hA], t['ab'][pa,pA,hc,hC], optimize=True)
	X['a'][pv,hc] += 1.0 * np.einsum('aIbA,AI,bi->ai', h['ab'][v,C,v,V], t['b'][pV,hC], t['a'][pv,hc], optimize=True)
	X['a'][pv,hc] += -1.0 * np.einsum('aUbA,uVvU,bu,vAiV->ai', h['ab'][v,A,v,V], lambdas['ab'], t['a'][pv,ha], t['ab'][pa,pV,hc,hA], optimize=True)
