	X['aa'][pv,pv,hc,hc] += -1.0 * np.einsum('aIuA,uUvV,bAiU,vVjI->abij', h['ab'][v,C,a,V], lambdas['ab'], t['ab'][pv,pV,hc,hA], t['ab'][pa,pA,hc,hC], optimize=True)
	X['aa'][pv,pv,hc,hc] += -1.0 * np.einsum('aIcU,uUvV,bciu,vVjI->abij', h['ab'][v,C,v,A], lambdas['ab'], t['aa'][pv,pv,hc,ha], t['ab'][pa,pA,hc,hC], optimize=True)
	X['aa'][pv,pv,hc,hc] += -0.5 * np.einsum('aIcU,uUvV,bVuI,vcij->abij', h['ab'][v,C,v,A], lambdas['ab'], t['ab'][pv,pA,ha,hC], t['aa'][pa,pv,hc,hc], optimize=True)
	X['aa'][pv,pv,hc,hc] += 1.0 * np.einsum('aIcA,ci,bAjI->abij', h['ab'][v,C,v,V], t['a'][pv,hc], t['ab'][pv,pV,hc,hC], optimize=True)
	X['aa'][pv,pv,hc,hc] += -0.5 * np.einsum('aIcA,AI,bcij->abij', h['ab'][v,C,v,V], t['b'][pV,hC], t['aa'][pv,pv,hc,hc], optimize=True)
	X['aa'][pv,pv,hc,hc] += 1.0 * np.einsum('aUcA,uVvU,bciu,vAjV->abij', h['ab'][v,A,v,V], lambdas['ab'], t['aa'][pv,pv,hc,ha], t['ab'][pa,pV,hc,hA], optimize=True)
	X['aa'][pv,pv,hc,hc] += 0.5 * np.einsum('aUcA,uVvU,bAuV,vcij->abij', h['ab'][v,A,v,V], lambdas['ab'], t['ab'][pv,pV,ha,hA], t['aa'][pa,pv,hc,hc], optimize=True)
	X['aa'][pv,pv,hc,hc] += 0.25 * np.einsum('IJUV,UVWX,aWiI,bXjJ->abij', h['bb'][C,C,A,A], lambdas['bb'], t['ab'][pv,pA,hc,hC], t['ab'][pv,pA,hc,hC], optimize=True)
	X['aa'][pv,pv,hc,hc] += 0.5 * np.einsum('IJAB,aAiI,bBjJ->abij', h['bb'][C,C,V,V], t['ab'][pv,pV,hc,hC], t['ab'][pv,pV,hc,hC], optimize=True)
	X['aa'][pv,pv,hc,hc] += 1.0 * np.einsum('IUVA,VWUX,aAiW,bXjI->abij', h['bb'][C,A,A,V], lambdas['bb'], t['ab'][pv,pV,hc,hA], t['ab'][pv,pA,hc,hC], optimize=True)
	X['aa'][pv,pv,hc,hc] += -0.25 * np.einsum('UVAB,WXUV,aAiX,bBjW->abij', h['bb'][A,A,V,V], lambdas['bb'], t['ab'][pv,pV,hc,hA], t['ab'][pv,pV,hc,hA], optimize=True)
	toc = time.time()
	elapsed_time = toc - tic
	if verbose:
		print(f'Took {elapsed_time} seconds.')
	return X
